"""Querying and adjusting the privileges held by the current process."""

from .errors import WTokenError
from ._winapi import (
    is_windows,
    open_process_token,
    close_handle,
    lookup_privilege_value,
    lookup_privilege_name,
    get_token_privileges,
    adjust_token_privilege,
    TOKEN_QUERY,
    TOKEN_ADJUST_PRIVILEGES,
)


def _ensure_windows(operation="this operation"):
    """Raise ``WTokenError(unsupported)`` when not on Windows."""
    if not is_windows():
        raise WTokenError(
            "%s requires Windows" % operation,
            kind="unsupported",
        )


def _open_token_for_query():
    """Open the current process token for reading."""
    try:
        return open_process_token(TOKEN_QUERY)
    except OSError as exc:
        raise WTokenError("cannot open process token: %s" % exc, kind="os") from exc


def _open_token_for_adjust():
    """Open the current process token for reading and adjustment."""
    try:
        return open_process_token(TOKEN_QUERY | TOKEN_ADJUST_PRIVILEGES)
    except OSError as exc:
        raise WTokenError("cannot open process token: %s" % exc, kind="os") from exc


def privileges():
    """Return ``{name: enabled}`` for every privilege the token holds.

    The mapping includes **every** privilege present in the token, whether it
    is currently enabled or not.  The boolean value reports only the enabled
    state; use :func:`has_privilege` to ask whether a privilege is held at all.
    """
    _ensure_windows("privilege enumeration")
    handle = _open_token_for_query()
    try:
        pairs = get_token_privileges(handle)
    except OSError as exc:
        raise WTokenError("cannot read token privileges: %s" % exc, kind="os") from exc
    finally:
        close_handle(handle)
    return dict(pairs)


def has_privilege(name):
    """Return ``True`` when the token holds ``name``, regardless of its state.

    A privilege that is held but currently disabled still counts as held.
    Returns ``False`` for names the token does not hold at all.
    """
    _ensure_windows("privilege query")
    if not isinstance(name, str) or not name:
        raise WTokenError("privilege name must be a non-empty string", kind="badarg")
    table = privileges()
    return name in table


def set_privilege(name, enabled=True):
    """Switch a held privilege on or off.

    The change takes effect immediately on the current process token and can be
    observed by any subsequent call to :func:`privileges` or by an external
    reader that opens the same token.

    Raises :class:`WTokenError` with ``kind="badarg"`` if *name* is empty or
    not held by the token, and ``kind="os"`` if the system refuses the change.
    """
    _ensure_windows("privilege adjustment")
    if not isinstance(name, str) or not name:
        raise WTokenError(
            "privilege name must be a non-empty string",
            kind="badarg",
            privilege=name if isinstance(name, str) else None,
        )

    # Resolve the name to a LUID first – this also validates the name exists
    # as a system-known privilege.
    try:
        luid = lookup_privilege_value(name)
    except OSError:
        raise WTokenError(
            "unknown privilege: %r" % (name,),
            kind="badarg",
            privilege=name,
        )

    # Verify the token actually holds this privilege before attempting to
    # adjust it.  AdjustTokenPrivileges silently succeeds even when the
    # privilege is not held (returning ERROR_NOT_ALL_ASSIGNED via
    # GetLastError), so we check explicitly.
    table = privileges()
    if name not in table:
        raise WTokenError(
            "the token does not hold privilege %r" % (name,),
            kind="badarg",
            privilege=name,
        )

    handle = _open_token_for_adjust()
    try:
        adjust_token_privilege(handle, luid, bool(enabled))
    except OSError as exc:
        # ERROR_NOT_ALL_ASSIGNED means the privilege isn't held
        if getattr(exc, "winerror", None) == 1300 or getattr(exc, "args", (None,))[0] == 1300:
            raise WTokenError(
                "the token does not hold privilege %r" % (name,),
                kind="badarg",
                privilege=name,
            ) from exc
        raise WTokenError(
            "failed to adjust privilege %r: %s" % (name, exc),
            kind="os",
            privilege=name,
        ) from exc
    finally:
        close_handle(handle)


def privilege_luid(name):
    """Return the system LUID for a privilege name, as an integer.

    The returned value matches what the operating system uses internally and
    can be passed to :func:`privilege_name` to recover the original name.
    """
    _ensure_windows("privilege lookup")
    if not isinstance(name, str) or not name:
        raise WTokenError(
            "privilege name must be a non-empty string",
            kind="badarg",
            privilege=name if isinstance(name, str) else None,
        )
    try:
        return lookup_privilege_value(name)
    except OSError:
        raise WTokenError(
            "unknown privilege: %r" % (name,),
            kind="badarg",
            privilege=name,
        )


def privilege_name(luid):
    """Return the privilege name for a system LUID.

    Accepts the integer form returned by :func:`privilege_luid`.
    """
    _ensure_windows("privilege lookup")
    try:
        luid_int = int(luid)
    except (TypeError, ValueError):
        raise WTokenError(
            "a privilege identifier must be an integer, got %r" % (luid,),
            kind="badarg",
        )
    if luid_int < 0:
        raise WTokenError(
            "unknown privilege identifier: %r" % (luid,),
            kind="badarg",
        )
    try:
        return lookup_privilege_name(luid_int)
    except OSError:
        raise WTokenError(
            "unknown privilege identifier: %r" % (luid,),
            kind="badarg",
        )

"""Elevation and integrity state of the current process."""

from .errors import WTokenError
from ._winapi import (
    is_windows,
    open_process_token,
    close_handle,
    get_token_elevation,
    get_token_integrity_level,
    TOKEN_QUERY,
)


def _ensure_windows(operation="this operation"):
    """Raise ``WTokenError(unsupported)`` when not on Windows."""
    if not is_windows():
        raise WTokenError(
            "%s requires Windows" % operation,
            kind="unsupported",
        )


def elevation():
    """Return ``{"elevated": bool, "type": str}`` for the current token.

    ``elevated`` is ``True`` when the token carries administrative privileges
    beyond those of a standard user.  ``type`` is one of ``"default"``,
    ``"full"``, or ``"limited"``, matching the Windows elevation type
    enumeration.
    """
    _ensure_windows("elevation query")
    try:
        handle = open_process_token(TOKEN_QUERY)
    except OSError as exc:
        raise WTokenError("cannot open process token: %s" % exc, kind="os") from exc
    try:
        elevated, type_name = get_token_elevation(handle)
    except OSError as exc:
        raise WTokenError("cannot query token elevation: %s" % exc, kind="os") from exc
    finally:
        close_handle(handle)
    return {"elevated": elevated, "type": type_name}


def integrity_level():
    """Return the mandatory integrity level name of the current token.

    Returns one of ``"untrusted"``, ``"low"``, ``"medium"``,
    ``"mediumplus"``, ``"high"``, or ``"system"``.
    """
    _ensure_windows("integrity query")
    try:
        handle = open_process_token(TOKEN_QUERY)
    except OSError as exc:
        raise WTokenError("cannot open process token: %s" % exc, kind="os") from exc
    try:
        level = get_token_integrity_level(handle)
    except OSError as exc:
        raise WTokenError("cannot query token integrity: %s" % exc, kind="os") from exc
    finally:
        close_handle(handle)
    return level
